-- ============================================================
-- 26 wm new patient rules
--
-- Generated by scripts/publish-wm-new-patient-rules.ts. Regenerate rather
-- than edit.
--
-- Gives "Weight Management — New Patient" its own ruleset: the 6 ELIGIBILITY rules from the
-- repeat ruleset, and none of the ones about ongoing treatment.
--
-- Copied rather than shared because ruleset_version belongs to one service.
-- That is also the better shape — a new-patient threshold and a repeat
-- threshold are separate decisions and should be tunable separately.
--
-- Filtered because 18 of the repeat ruleset's 24 rules ask about treatment so
-- far: adverse effects, doses missed, weeks on the current strength, weight
-- lost since starting, fluid intake, appetite suppression. A patient who has
-- not started answers none of those, so those rules skip and decide nothing.
-- Copying them would put 18 rules on the screen that can never fire.
--
-- Included:
--   RED   p1000 Pregnant or breastfeeding
--   RED   p990  Wegovy outside the 18–74 age range
--   RED   p990  Mounjaro outside the 18–84 age range
--   RED   p930  BMI under 23 and not requesting a decrease
--   GREEN p920  BMI under 23 with a decrease request (tapering)
--   AMBER p700  BMI between 23 and 24.9
--
-- What changes for a patient: today every new-patient request comes back AMBER
-- with no reason attached, because the service has no ruleset. After this,
-- pregnancy, an out-of-range age and a BMI under 23 come back RED with the
-- rule named, and a BMI of 23–24.9 comes back AMBER for the same reason.
--
-- Safe to run more than once? NO. Each run publishes another version.
-- ============================================================

begin;

with next as (
  select coalesce(max(version), 0) + 1 as v
    from public.ruleset_version
   where service_id = 'a8734e8a-b774-5363-92f5-3a5269d908c4'::uuid
),
inserted as (
  insert into public.ruleset_version
    (organisation_id, service_id, version, definition, published_at)
  select 'e91b8b9a-54e8-55a1-8412-d3ade3da0b53'::uuid,
         'a8734e8a-b774-5363-92f5-3a5269d908c4'::uuid,
         next.v,
         $json${"schemaVersion":1,"defaultOutcome":"AMBER","rules":[{"id":"pregnancy","when":{"op":"eq","field":"answers.pregnancy","value":"yes"},"label":"Pregnant or breastfeeding","message":"Pregnancy or breastfeeding declared. Treatment must be discontinued.","outcome":"RED","priority":1000,"patientMessage":"We cannot supply this treatment at the moment. Please stop taking your medicine and contact the pharmacy."},{"id":"age-wegovy","when":{"all":[{"op":"eq","field":"derived.medicine","value":"Wegovy"},{"any":[{"op":"lt","field":"derived.age","value":18},{"op":"gt","field":"derived.age","value":74}]}]},"label":"Wegovy outside the 18–74 age range","message":"Outside the licensed age range for Wegovy (18–74).","outcome":"RED","priority":990},{"id":"age-mounjaro","when":{"all":[{"op":"eq","field":"derived.medicine","value":"Mounjaro"},{"any":[{"op":"lt","field":"derived.age","value":18},{"op":"gt","field":"derived.age","value":84}]}]},"label":"Mounjaro outside the 18–84 age range","message":"Outside the licensed age range for Mounjaro (18–84).","outcome":"RED","priority":990},{"id":"bmi-low-not-decreasing","when":{"all":[{"op":"lt","field":"derived.bmi","value":23},{"op":"neq","field":"answers.doseRequest","value":"decrease"}]},"label":"BMI under 23 and not requesting a decrease","message":"BMI is below 23 and the patient is not tapering. Needs review in person.","outcome":"RED","priority":930},{"id":"bmi-low-tapering","when":{"all":[{"op":"lt","field":"derived.bmi","value":23},{"op":"eq","field":"answers.doseRequest","value":"decrease"}]},"label":"BMI under 23 with a decrease request (tapering)","advice":"Congratulations on reaching a healthy weight. Reducing your dose gradually is the right way to come off treatment — speak to us if you are unsure.","message":"Tapering at a healthy BMI. Appropriate to support.","outcome":"GREEN","priority":920},{"id":"bmi-borderline","when":{"op":"between","field":"derived.bmi","range":[23,24.9]},"label":"BMI between 23 and 24.9","message":"BMI is in the 23–24.9 band. Confirm continuing treatment remains appropriate.","outcome":"AMBER","priority":700}]}$json$::jsonb,
         now()
    from next
  returning id, version
)
update public.service
   set published_ruleset_version_id = inserted.id
  from inserted
 where public.service.id = 'a8734e8a-b774-5363-92f5-3a5269d908c4'::uuid;

commit;
